<?php
declare(strict_types=1);
defined('VV_ROOT') || exit;
use VV\Content;
$s=$app->state['settings'];
$pageTitle=$notFound?t('Page introuvable','Page not found'):($current?Content::field($current,'title'):$s['title']);
$pages=$app->publicItems('page'); usort($pages,fn($a,$b)=>$a['order']<=>$b['order']);
$cover=$app->state['media'][$s['cover']] ?? null; $avatar=$app->state['media'][$s['avatar']] ?? null;
$themeStyle=url('content/themes/'.$app->theme().'/style.css');
?><!doctype html><html lang="<?=e(lang())?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($pageTitle)?><?=($current || $notFound)?' · '.e($s['title']):''?></title><meta name="description" content="<?=e($current?(Content::field($current,'excerpt') ?: Content::summary(Content::field($current,'body'),160)):$s['tagline'])?>"><link rel="stylesheet" href="<?=e(url('assets/site.css'))?>"><link rel="stylesheet" href="<?=e($themeStyle)?>"><script src="<?=e(url('assets/site.js'))?>" defer></script><?php vv_do('head',$app,$current);?></head><body class="public-site"><a class="skip-link" href="#content"><?=e(t('Aller au contenu','Skip to content'))?></a><header class="site-top"><a class="site-brand" href="<?=e(url('index.php',['lang'=>lang()]))?>"><span class="brand-monogram"><?=e(mb_substr($s['title'],0,1))?><span>.</span></span><strong><?=e($s['title'])?></strong></a><form class="site-search" method="get" action="<?=e(url('index.php'))?>"><svg aria-hidden="true"><use href="<?=e(url('assets/icons.svg'))?>#search"></use></svg><input type="hidden" name="lang" value="<?=e(lang())?>"><input type="search" name="q" value="<?=e($query)?>" aria-label="<?=e(t('Rechercher dans les articles','Search posts'))?>" placeholder="<?=e(t('Chercher une idée, un projet…','Find an idea, a project…'))?>"><button class="sr-only"><?=e(t('Rechercher','Search'))?></button></form><a class="language-link" href="<?=e(url('index.php',array_merge(array_diff_key($_GET,['lang'=>1]),['lang'=>lang()==='fr'?'en':'fr'])))?>"><?=lang()==='fr'?'EN':'FR'?></a><button class="site-menu-button" type="button" aria-label="Menu" aria-expanded="false" aria-controls="profile-nav"><svg><use href="<?=e(url('assets/icons.svg'))?>#menu"></use></svg></button></header><div class="site-layout"><aside class="profile-rail"><a class="rail-home <?=!$current&&!$notFound?'selected':''?>" href="<?=e(url('index.php',['lang'=>lang()]))?>"><svg><use href="<?=e(url('assets/icons.svg'))?>#grid"></use></svg><?=e(t('Mon profil','My profile'))?></a><a href="<?=e(url('index.php',['feed'=>'1','lang'=>lang()]))?>"><svg><use href="<?=e(url('assets/icons.svg'))?>#article"></use></svg><?=e(t('Publications','Posts'))?></a><nav id="profile-nav" aria-label="Pages"><?php foreach($pages as $p):if(!$p['menu'])continue;?><a class="<?=$current && $current['id']===$p['id']?'selected':''?>" href="<?=e(Content::url($p))?>"><svg><use href="<?=e(url('assets/icons.svg'))?>#file"></use></svg><?=e(Content::field($p,'title'))?></a><?php endforeach;?></nav><?php vv_do('profile_links',$app);?><div class="rail-note"><span class="tiny-dot"></span><?=e(t('Un espace indépendant.','An independent space.'))?></div></aside><main id="content" class="profile-feed"><?php if($preview!==''):?><div class="preview-banner"><?=e(t('Aperçu privé du propriétaire','Private owner preview'))?> · <a href="<?=e(admin_url('editor',['id'=>$preview]))?>"><?=e(t('Revenir à l’éditeur','Back to editor'))?></a></div><?php endif;?><?php if(!$current && !$notFound && !$query && val($_GET,'feed')!=='1'):?><section class="profile-header"><div class="profile-cover"><?php if($cover):?><img src="<?=e(url('media.php',['id'=>$cover['id']]))?>" alt="<?=e($cover['alt'])?>"><?php else:?><div class="cover-words" aria-hidden="true">CREATE.<br>SHARE.<span>CONNECT.</span></div><span class="cover-number">01 / PERSONAL SPACE</span><?php endif;?></div><div class="profile-details"><div class="avatar-row"><div class="profile-avatar"><?php if($avatar):?><img src="<?=e(url('media.php',['id'=>$avatar['id']]))?>" alt="<?=e($avatar['alt'])?>"><?php else:?><span><?=e(mb_strtoupper(mb_substr($s['title'],0,1)))?><i>.</i></span><?php endif;?></div><?php if($s['email_public']):?><a class="site-button" href="<?=e('mailto:'.$s['email_public'])?>"><?=e(t('Me contacter','Contact me'))?></a><?php endif;?></div><div class="profile-name"><h1><?=e($s['title'])?></h1><span class="profile-check" aria-hidden="true">✓</span></div><p class="tagline"><?=e($s['tagline'])?></p><p class="profile-bio"><?=nl2br(e($s['bio']))?></p><div class="profile-meta"><?php if($s['location']):?><span><svg><use href="<?=e(url('assets/icons.svg'))?>#pin"></use></svg><?=e($s['location'])?></span><?php endif;?><?php foreach(explode("\n",$s['socials']) as $social):$social=Content::link(trim($social));if(!str_starts_with($social,'https://'))continue;?><a href="<?=e($social)?>" target="_blank" rel="noopener noreferrer"><?=e(parse_url($social,PHP_URL_HOST) ?: t('Lien','Link'))?></a><?php endforeach;?></div><div class="profile-counts"><span><strong><?=count($app->publicItems('post'))?></strong> <?=e(t('publications','posts'))?></span><span><strong><?=count($pages)?></strong> <?=e(t('pages','pages'))?></span></div><?php vv_do('profile_after',$app);?></div></section><?php endif;?><?php if($notFound):?><section class="not-found"><span class="eyebrow">404</span><h1><?=e(t('Cette page a pris un autre chemin.','This page took another path.'))?></h1><p><?=e(t('Retrouvez les dernières publications et les pages du profil.','Find the latest posts and profile pages.'))?></p><a class="site-button" href="<?=e(url('index.php',['lang'=>lang()]))?>"><?=e(t('Retour au profil','Back to profile'))?></a></section><?php elseif($current):?><article class="single-article"><a class="back-link" href="<?=e(url('index.php',['lang'=>lang()]))?>"><?=e(t('Retour au profil','Back to profile'))?></a><div class="post-meta"><span class="post-category"><?=e($current['type']==='page'?t('PAGE','PAGE'):t('PUBLICATION','POST'))?></span><time datetime="<?=e(gmdate('c',$current['publish_at']))?>"><?=e(gmdate('d.m.Y',$current['publish_at']))?></time></div><h1><?=e(Content::field($current,'title'))?></h1><?php if(Content::field($current,'excerpt')):?><p class="article-excerpt"><?=e(Content::field($current,'excerpt'))?></p><?php endif;?><?php if($current['cover']):?><img class="article-cover" src="<?=e(url('media.php',['id'=>$current['cover']]))?>" alt="<?=e($app->state['media'][$current['cover']]['alt'] ?? '')?>"><?php endif;?><div class="prose"><?=$app->body($current)?></div><div class="post-tags"><?php foreach($current['tags'] as $tag):?><a href="<?=e(url('index.php',['q'=>$tag,'lang'=>lang()]))?>">#<?=e($tag)?></a><?php endforeach;?></div><button class="share-button" type="button" data-share="<?=e(Content::url($current))?>" data-title="<?=e(Content::field($current,'title'))?>"><svg><use href="<?=e(url('assets/icons.svg'))?>#share"></use></svg><?=e(t('Partager cette publication','Share this post'))?></button></article><?php else:?><div class="feed-heading"><h2><?=e($query?t('Résultats pour « ','Results for “').$query.(lang()==='fr'?' »':'”'):t('Publications','Posts'))?></h2><span><?=e($query?(string)$total:t('LES DERNIÈRES IDÉES','LATEST IDEAS'))?></span></div><?php if(!$items):?><div class="empty-state"><svg><use href="<?=e(url('assets/icons.svg'))?>#article"></use></svg><h2><?=e(t('Le fil attend de nouvelles idées.','The feed is waiting for new ideas.'))?></h2><p><?=e(t('Les prochaines publications apparaîtront ici.','New posts will appear here.'))?></p></div><?php endif;?><?php foreach($items as $c):?><article class="feed-card"><?php if($c['pinned']):?><div class="pinned-label"><svg><use href="<?=e(url('assets/icons.svg'))?>#pin"></use></svg><?=e(t('Publication épinglée','Pinned post'))?></div><?php endif;?><div class="post-author"><span class="mini-avatar"><?php if($avatar):?><img src="<?=e(url('media.php',['id'=>$avatar['id']]))?>" alt=""><?php else:?><?=e(mb_substr($s['title'],0,1))?><?php endif;?></span><div><strong><?=e($s['title'])?></strong><time datetime="<?=e(gmdate('c',$c['publish_at']))?>"><?=e(gmdate('d.m.Y',$c['publish_at']))?></time></div></div><a class="post-content-link" href="<?=e(Content::url($c))?>"><h2><?=e(Content::field($c,'title'))?></h2><p><?=e(Content::field($c,'excerpt') ?: Content::summary(Content::field($c,'body'),260))?></p><?php if($c['cover']):?><img class="feed-cover" src="<?=e(url('media.php',['id'=>$c['cover']]))?>" alt="<?=e($app->state['media'][$c['cover']]['alt'] ?? '')?>" loading="lazy"><?php endif;?></a><div class="post-tags"><?php foreach($c['tags'] as $tag):?><a href="<?=e(url('index.php',['q'=>$tag,'lang'=>lang()]))?>">#<?=e($tag)?></a><?php endforeach;?></div><div class="post-bottom"><a href="<?=e(Content::url($c))?>"><?=e(t('Lire la publication','Read post'))?></a><button class="share-button" type="button" data-share="<?=e(Content::url($c))?>" data-title="<?=e(Content::field($c,'title'))?>"><svg><use href="<?=e(url('assets/icons.svg'))?>#share"></use></svg><?=e(t('Partager','Share'))?></button></div></article><?php endforeach;?><div class="feed-pagination"><?php if($page>1):?><a class="site-button" href="<?=e(url('index.php',['page'=>$page-1,'q'=>$query,'feed'=>'1','lang'=>lang()]))?>"><?=e(t('Précédent','Previous'))?></a><?php endif;?><?php if($total>$page*$per):?><a class="site-button" href="<?=e(url('index.php',['page'=>$page+1,'q'=>$query,'feed'=>'1','lang'=>lang()]))?>"><?=e(t('Suivant','Next'))?></a><?php endif;?></div><?php endif;?><footer class="site-footer"><span><?=e($s['footer'])?></span><a href="<?=e(url('admin.php',['lang'=>lang()]))?>"><?=e(t('Administration','Administration'))?></a></footer></main><aside class="context-rail"><div class="context-card"><span class="eyebrow"><?=e(t('EXPLORER LE PROFIL','EXPLORE THE PROFILE'))?></span><h2><?=e(t('Chaque idée a sa place.','Every idea has its place.'))?></h2><p><?=e(t('Publications, projets, notes et nouvelles perspectives.','Posts, projects, notes and new perspectives.'))?></p></div><div class="context-card"><h3><?=e(t('À découvrir','Discover'))?></h3><?php foreach(array_slice($pages,0,5) as $p):?><a class="context-page" href="<?=e(Content::url($p))?>"><?=e(Content::field($p,'title'))?><span>•</span></a><?php endforeach;?></div><?php vv_do('sidebar',$app);?></aside></div><div id="site-toast" role="status" aria-live="polite"></div><?php vv_do('footer',$app);?></body></html>
